import React, { useLayoutEffect, useRef } from 'react';
import { useLocation } from 'react-router-dom';
import { bindScrollFlow } from './scrollFlow.js';

export default function ScrollFlow({ children }) {
  const { pathname } = useLocation();
  const rootRef = useRef(null);

  useLayoutEffect(() => {
    const root = rootRef.current;
    if (!root) return undefined;
    return bindScrollFlow(root);
  }, [pathname]);

  return (
    <div className="mmc-scroll-flow" ref={rootRef}>
      {children}
    </div>
  );
}
